result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/world.py", "content": """"Lockstep command-queue simulator.

Units live on an integer grid. Commands (move dx,dy / halt) are scheduled
for specific tick numbers. Each call to step() applies every command due
that tick in deterministic order -- (tick, unit_id, insertion_order) --
then advances movement. Determinism is total: the same set of commands,
inserted in any order, yields a bit-identical world.
"""

from __future__ import annotations

import hashlib
import itertools
from dataclasses import dataclass


class Command:
    """Base class for scheduled commands."""

    __slots__ = ("tick", "unit_id", "insertion_order")

    def __init__(self, tick: int, unit_id: int, insertion_order: int):
        self.tick = tick
        self.unit_id = unit_id
        self.insertion_order = insertion_order

    # --- stable repr used for hashing -------------------------------------
    def _payload(self) -> str:
        raise NotImplementedError

    def __repr__(self) -> str:
        return f"{type(self).__name__}(tick={self.tick}, unit_id={self.unit_id}, {self._payload()})"

    def sort_key(self):
        return (self.tick, self.unit_id, self.insertion_order)


@dataclass(frozen=True)
class Move(Command):
    dx: int
    dy: int

    __slots__ = ()

    def _payload(self) -> str:
        return f"dx={self.dx}, dy={self.dy}"

    def apply(self, world: World, unit_id: int) -> None:
        world.units[unit_id].vx = self.dx
        world.units[unit_id].vy = self.dy


@dataclass(frozen=True)
class Halt(Command):
    __slots__ = ()

    def _payload(self) -> str:
        return ""

    def apply(self, world: World, unit_id: int) -> None:
        u = world.units[unit_id]
        u.vx = 0
        u.vy = 0


@dataclass(frozen=True)
class Teleport(Command):
    x: int
    y: int

    __slots__ = ()

    def _payload(self) -> str:
        return f"x={self.x}, y={self.y}"

    def apply(self, world: World, unit_id: int) -> None:
        u = world.units[unit_id]
        u.x = self.x
        u.y = self.y


class Unit:
    __slots__ = ("id", "x", "y", "vx", "vy")

    def __init__(self, uid: int, x: int, y: int):
        self.id = uid
        self.x = x
        self.y = y
        self.vx = 0
        self.vy = 0

    def advance(self) -> None:
        self.x += self.vx
        self.y += self.vy

    def state_repr(self) -> str:
        return f"Unit(id={self.id}, x={self.x}, y={self.y}, vx={self.vx}, vy={self.vy})"


class World:
    def __init__(self, tick: int = 0):
        self.tick = tick
        self.units: dict[int, Unit] = {}
        self._queue: list[Command] = []
        self._order_counter = itertools.count()

    def add_unit(self, uid: int, x: int, y: int) -> Unit:
        if uid in self.units:
            raise ValueError(f"duplicate unit id {uid}")
        self.units[uid] = Unit(uid, x, y)
        return self.units[uid]

    def schedule(self, cmd_cls, tick: int, unit_id: int, **kw) -> Command:
        """Schedule a command for a future tick. Insertion order is recorded."""
        cmd = cmd_cls(tick=tick, unit_id=unit_id,
                      insertion_order=next(self._order_counter), **kw)
        if tick < self.tick:
            raise ValueError(f"cannot schedule at tick {tick} < current {self.tick}")
        self._queue.append(cmd)
        return cmd

    def step(self) -> int:
        """Apply all commands due this tick in (tick, unit_id, insertion_order),
        then advance all units by their velocity."""
        t = self.tick
        due = sorted((c for c in self._queue if c.tick == t), key=Command.sort_key)
        self._queue = [c for c in self._queue if c.tick != t]
        for cmd in due:
            if cmd.unit_id not in self.units:
                raise KeyError(f"command targets unknown unit {cmd.unit_id}")
            cmd.apply(self, cmd.unit_id)
        for uid in sorted(self.units):
            self.units[uid].advance()
        self.tick += 1
        return self.tick

    def run_until(self, target_tick: int) -> None:
        while self.tick < target_tick:
            self.step()

    def hash(self) -> str:
        """Stable sha256 over tick, unit states and pending commands."""
        h = hashlib.sha256()
        h.update(f"tick={self.tick};".encode())
        for uid in sorted(self.units):
            h.update(self.units[uid].state_repr().encode())
            h.update(b";")
        for cmd in sorted(self._queue, key=Command.sort_key):
            h.update(repr(cmd).encode())
            h.update(b";")
        return h.hexdigest()
